node -e "
// Simulate the buildProviders function
function formatProviderLabel(key) {
  const labels = {
    'ticketmaster': 'Ticketmaster',
    'kulturhuset': 'Kulturhuset',
    'stockholm': 'Stockholm',
    'malmo-live': 'Malmö Live',
  };
  return labels[key] || key;
}
const FALLBACK_PROVIDERS = [
  { key: 'all', label: 'Alla arrangörer' },
  { key: 'ticketmaster', label: 'Ticketmaster' },
  { key: 'stockholm', label: 'Stockholm' },
  { key: 'kulturhuset', label: 'Kulturhuset' },
  { key: 'malmo-live', label: 'Malmö Live' },
];
function buildProviders(availableSources) {
  if (!availableSources || availableSources.length === 0) {
    return FALLBACK_PROVIDERS;
  }

  const normalizedSources = availableSources.map(s => {
    if (typeof s === 'string') {
      return { key: s, label: formatProviderLabel(s) };
    }
    return { key: s.key, label: s.label || formatProviderLabel(s.key) };
  });

  return [
    { key: 'all', label: 'Alla arrangörer' },
    ...normalizedSources,
  ];
}
// Test with string array (from Supabase)
const stringSources = ['ticketmaster', 'kulturhuset', 'stockholm'];
const result1 = buildProviders(stringSources);
console.log('String sources:', result1.map(p => p.key));
// Test with object array (legacy format)
const objectSources = [
  { key: 'ticketmaster', label: 'Ticketmaster' },
  { key: 'kulturhuset', label: 'Kulturhuset' },
];
const result2 = buildProviders(objectSources);
console.log('Object sources:', result2.map(p => p.key));
// Check for unique keys
const keys1 = result1.map(p => p.key);
const uniqueKeys1 = [...new Set(keys1)];
console.log('Unique keys match:', keys1.length === uniqueKeys1.length);
console.log('All keys unique:', keys1.length === uniqueKeys1.length);
"
